'use strict';
/* Final stability validation: canonical Q408 vs Q490. */
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function atr(c,p=14){const a=Array(c.length).fill(NaN),q=[];let s=0;for(let i=1;i<c.length;i++){const tr=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c));q.push(tr);s+=tr;if(q.length>p)s-=q.shift();if(q.length===p)a[i]=s/p}return a}function adx(c,p=14){const o=Array(c.length).fill(NaN),tr=Array(c.length).fill(0),pd=Array(c.length).fill(0),md=Array(c.length).fill(0);for(let i=1;i<c.length;i++){const up=c[i].h-c[i-1].h,dn=c[i-1].l-c[i].l;pd[i]=up>dn&&up>0?up:0;md[i]=dn>up&&dn>0?dn:0;tr[i]=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c))}let tn=0,pn=0,mn=0;for(let i=1;i<=p;i++){tn+=tr[i];pn+=pd[i];mn+=md[i]}const dx=Array(c.length).fill(NaN);for(let i=p;i<c.length;i++){if(i>p){tn=tn-tn/p+tr[i];pn=pn-pn/p+pd[i];mn=mn-mn/p+md[i]}if(tn>0){const a=100*pn/tn,b=100*mn/tn;if(a+b>0)dx[i]=100*Math.abs(a-b)/(a+b)}}let seed=0,n=0,last=NaN;for(let i=p;i<c.length;i++){if(!Number.isFinite(dx[i]))continue;if(n<p){seed+=dx[i];n++;if(n===p)last=o[i]=seed/p}else last=o[i]=(last*(p-1)+dx[i])/p}return o}const A=atr(M),X=adx(M),BASE={bb:2.2,sb:2.6,w:.30,r:.15,ax:35,bm:.55,blocks:[1,5]},Q={bb:2.2,sb:2.6,w:.30,r:.15,ax:32,bm:.50,blocks:[1,5,23]};
function run(q){let out=[],p=null;for(let i=250;i<M.length-1;i++){if(p){const b=M[i],sl=p.side==='BUY'?b.l<=p.sl:b.h>=p.sl,tp=p.side==='BUY'?b.h>=p.tp:b.l<=p.tp;if(sl||tp||i-p.ei+1>=3){const px=sl?p.sl:tp?p.tp:b.c;out.push({t:p.t,r:(p.side==='BUY'?px-p.en:p.en-px)/p.risk,s:p.side});p=null}}if(p)continue;const ex=i-1;if(!Number.isFinite(A[ex])||!Number.isFinite(X[ex]))continue;const hr=new Date(M[ex].t).getUTCHours();if(q.blocks.includes(hr)||X[ex]>q.ax)continue;const b=M[ex],rg=b.h-b.l;if(!(rg>0)||Math.abs(b.c-b.o)/rg>q.bm)continue;const disp=M[ex-1].c-M[ex-3].c;if(!disp)continue;const side=disp<0?'BUY':'SELL',burst=side==='BUY'?q.bb:q.sb;if(Math.abs(disp)<A[ex]*burst)continue;let agree=0;for(let k=ex-3;k<ex;k++){if(disp>0&&M[k].c>M[k].o)agree++;if(disp<0&&M[k].c<M[k].o)agree++}if(agree<2)continue;const uw=(b.h-Math.max(b.o,b.c))/rg,lw=(Math.min(b.o,b.c)-b.l)/rg;if(side==='BUY'&&lw<q.w)continue;if(side==='SELL'&&uw<q.w)continue;const cf=M[i];if(side==='BUY'){if(cf.c<=b.l+rg*q.r||cf.l<b.l-A[ex]*.25)continue}else if(cf.c>=b.h-rg*q.r||cf.h>b.h+A[ex]*.25)continue;const en=M[i+1].o,risk=Math.max(A[ex]*1.75,2),reward=Math.max(A[ex]*1.5,2);p={side,en,risk,sl:side==='BUY'?en-risk:en+risk,tp:side==='BUY'?en+reward:en-reward,ei:i+1,t:M[i].t}}return out}
function S(a){let w=0,gp=0,gl=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else if(x.r<0){gl-=x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`,B=run(BASE),C=run(Q),end=M.at(-1).t;function line(n,a,b){console.log(n.padEnd(12),`Q408 ${F(S(a))} | Q490 ${F(S(b))}`)}console.log('EXHAUSTION Q490 — FINAL STABILITY VALIDATION');console.log(`M5 ${M.length} | ${new Date(M[0].t).toISOString().slice(0,10)} → ${new Date(end).toISOString().slice(0,10)}`);line('FULL',B,C);if(!(S(B).n===207&&Math.abs(S(B).net-23.44)<1)){console.log('❌ BASE PARITY FAIL');process.exit(3)}console.log('✅ BASE PARITY OK');console.log('\nCHRONO QUARTERS');for(let k=0;k<4;k++){const lo=M[Math.floor(M.length*k/4)].t,hi=k===3?Infinity:M[Math.floor(M.length*(k+1)/4)].t;line('Q'+(k+1),B.filter(x=>x.t>=lo&&x.t<hi),C.filter(x=>x.t>=lo&&x.t<hi))}console.log('\nROLLING');for(const d of [180,120,90,60,30]){const lo=end-d*864e5;line(d+'D',B.filter(x=>x.t>=lo),C.filter(x=>x.t>=lo))}console.log('\n5 FOLDS');let stable=0;for(let k=0;k<5;k++){const lo=M[Math.floor(M.length*k/5)].t,hi=k===4?Infinity:M[Math.floor(M.length*(k+1)/5)].t,ca=C.filter(x=>x.t>=lo&&x.t<hi);line('F'+(k+1),B.filter(x=>x.t>=lo&&x.t<hi),ca);const s=S(ca);if(s.n>=20&&s.pf>=1.05&&s.net>0)stable++}console.log('\nSIDE CHECK');line('BUY',B.filter(x=>x.s==='BUY'),C.filter(x=>x.s==='BUY'));line('SELL',B.filter(x=>x.s==='SELL'),C.filter(x=>x.s==='SELL'));const a=S(C),r120=S(C.filter(x=>x.t>=end-120*864e5)),r90=S(C.filter(x=>x.t>=end-90*864e5));const pass=stable>=4&&a.n>=150&&a.wr>=62&&a.pf>=1.65&&a.net>=S(B).net&&a.dd<=S(B).dd+.05&&r120.pf>=1.4&&r90.pf>=1.4;console.log(`\nBALANCED GATE: ${pass?'✅ PASS':'❌ FAIL'} | stable folds=${stable}/5 | 120D ${F(r120)} | 90D ${F(r90)}`);